import java.time.LocalDate;

public class DateFormatterUtilTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("pretty pads the day", "Mar 05, 2026", DateFormatterUtil.pretty(LocalDate.of(2026, 3, 5)));
            check("pretty on a December date", "Dec 25, 2024", DateFormatterUtil.pretty(LocalDate.of(2024, 12, 25)));
            check("pretty on the first of January", "Jan 01, 2023", DateFormatterUtil.pretty(LocalDate.of(2023, 1, 1)));
            check("parseSlash single-digit month and day", LocalDate.of(2026, 3, 5), DateFormatterUtil.parseSlash("3/5/2026"));
            check("parseSlash two-digit month and day", LocalDate.of(1999, 12, 31), DateFormatterUtil.parseSlash("12/31/1999"));
            check("parseSlash leap day", LocalDate.of(2024, 2, 29), DateFormatterUtil.parseSlash("2/29/2024"));
            check("round trip parse then pretty", "Jul 04, 2025", DateFormatterUtil.pretty(DateFormatterUtil.parseSlash("7/4/2025")));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
