import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

public class DateFormatterUtil {

    private static final DateTimeFormatter PRETTY =
            DateTimeFormatter.ofPattern("MMM dd, yyyy", Locale.US);

    private static final DateTimeFormatter SLASH =
            DateTimeFormatter.ofPattern("M/d/yyyy");

    public static String pretty(LocalDate d) {
        return d.format(PRETTY);
    }

    public static LocalDate parseSlash(String s) {
        return LocalDate.parse(s, SLASH);
    }
}
